{
  "project_id": "6e9012fcb5ac462fbdd7",
  "name": "restrict_storage_to_owners",
  "query": "-- Restrict Storage metadata and objects to the authenticated owner.
-- The owner_id column is the canonical Supabase Storage ownership field.
create index if not exists storage_objects_owner_id_idx
  on storage.objects (owner_id);

create index if not exists storage_buckets_owner_id_idx
  on storage.buckets (owner_id);

drop policy if exists "Users can view their own buckets" on storage.buckets;
create policy "Users can view their own buckets"
  on storage.buckets
  for select
  to authenticated
  using ((select auth.uid())::text = owner_id);

drop policy if exists "Users can view their own objects" on storage.objects;
create policy "Users can view their own objects"
  on storage.objects
  for select
  to authenticated
  using ((select auth.uid())::text = owner_id);

drop policy if exists "Users can upload their own objects" on storage.objects;
create policy "Users can upload their own objects"
  on storage.objects
  for insert
  to authenticated
  with check ((select auth.uid())::text = owner_id);

drop policy if exists "Users can update their own objects" on storage.objects;
create policy "Users can update their own objects"
  on storage.objects
  for update
  to authenticated
  using ((select auth.uid())::text = owner_id)
  with check ((select auth.uid())::text = owner_id);

drop policy if exists "Users can delete their own objects" on storage.objects;
create policy "Users can delete their own objects"
  on storage.objects
  for delete
  to authenticated
  using ((select auth.uid())::text = owner_id);"
}

